if (typeof globalThis.TextEncoder === "undefined") {
  globalThis.TextEncoder = class RankforgeTextEncoder {
    encode(value = "") {
      const encoded = encodeURIComponent(String(value));
      const bytes = [];
      for (let index = 0; index < encoded.length; index += 1) {
        if (encoded[index] === "%") {
          bytes.push(Number.parseInt(encoded.slice(index + 1, index + 3), 16));
          index += 2;
        } else {
          bytes.push(encoded.charCodeAt(index));
        }
      }
      return Uint8Array.from(bytes);
    }
  };
}
if (typeof globalThis.TextDecoder === "undefined") {
  globalThis.TextDecoder = class RankforgeTextDecoder {
    decode(value = new Uint8Array()) {
      const bytes = value instanceof Uint8Array ? value : new Uint8Array(value?.buffer || value);
      const encoded = Array.from(bytes, byte => `%${byte.toString(16).padStart(2, "0")}`).join("");
      try { return decodeURIComponent(encoded); }
      catch { return Array.from(bytes, byte => String.fromCharCode(byte)).join(""); }
    }
  };
}

