function exercisePictogram(exercise = {}, size = 20) {
  const equipment = String(exercise.equipment || '').toLowerCase();
  const key = equipment.includes('trap bar') || equipment.includes('farmer handles')
    ? 'trapbar'
    : equipment.includes('safety-bar')
      ? 'safetybar'
      : equipment.includes('langhantel') || equipment.includes('sz-stange') || equipment.includes('smith')
        ? 'barbell'
        : equipment.includes('kurzhantel')
          ? 'dumbbell'
          : equipment.includes('kettlebell')
            ? 'kettlebell'
            : equipment.includes('kabel')
              ? 'cable'
              : equipment.includes('plate-loaded') || equipment.includes('maschine')
                ? 'machine'
                : equipment.includes('körpergewicht') || equipment.includes('zusatzgewicht') || equipment.includes('gewichtsweste')
                  ? 'body'
                  : equipment.includes('landmine')
                    ? 'landmine'
                    : equipment.includes('schlitten')
                      ? 'sled'
                      : equipment.includes('widerstandsband')
                        ? 'band'
                        : equipment.includes('trx') || equipment.includes('ringe')
                          ? 'rings'
                          : equipment.includes('medizinball') || equipment.includes('gymnastikball')
                            ? 'medicineball'
                            : equipment.includes('belt squat')
                              ? 'belt'
                              : equipment.includes('gewichtsscheibe')
                                ? 'plate'
                                : equipment.includes('cardio') || equipment.includes('springseil')
                                  ? 'cardio'
                                  : 'other';
  return `<svg class="icon exercise-pictogram exercise-pictogram--${key}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${RF78_EQUIPMENT_ICONS[key]}</svg>`;
}

function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>'"]/g, character => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;"
  })[character]);
}

function escapeAttr(value) {
  return escapeHtml(value).replace(/`/g, "&#96;");
}

function deepClone(value) {
  return typeof structuredClone === "function" ? structuredClone(value) : JSON.parse(JSON.stringify(value));
}

function uid(prefix = "id") {
  return `${prefix}-${typeof crypto.randomUUID === "function" ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`}`;
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, Number(value) || 0));
}

const memoryStorage = {
  localStorage: new Map(),
  sessionStorage: new Map()
};

function safeStorage(name = "localStorage") {
  try { return window[name] || null; } catch { return null; }
}

function safeStorageGet(key, name = "localStorage") {
  const normalizedKey = String(key);
  try {
    const value = safeStorage(name)?.getItem(normalizedKey);
    if (value != null) {
      memoryStorage[name]?.set(normalizedKey, value);
      return value;
    }
  } catch {
    // Safari private mode and embedded previews can deny web storage.
  }
  return memoryStorage[name]?.get(normalizedKey) ?? null;
}

function safeStorageSet(key, value, name = "localStorage") {
  const normalizedKey = String(key);
  const normalizedValue = String(value);
  memoryStorage[name]?.set(normalizedKey, normalizedValue);
  try {
    const storage = safeStorage(name);
    if (!storage) return false;
    storage.setItem(normalizedKey, normalizedValue);
    return true;
  } catch {
    return false;
  }
}

function safeStorageRemove(key, name = "localStorage") {
  const normalizedKey = String(key);
  memoryStorage[name]?.delete(normalizedKey);
  try {
    const storage = safeStorage(name);
    if (!storage) return false;
    storage.removeItem(normalizedKey);
    return true;
  } catch {
    return false;
  }
}

function round(value, digits = 0) {
  const factor = 10 ** digits;
  return Math.round((Number(value) || 0) * factor) / factor;
}

function sum(values) {
  return values.reduce((total, value) => total + (Number(value) || 0), 0);
}

function normalizeAppearance(value) {
  return APPEARANCE_OPTIONS.has(value) ? value : "dark";
}

function normalizeHexColor(value, fallback = DEFAULT_ACCENT_COLOR) {
  const input = String(value || "").trim();
  const short = /^#([0-9a-f]{3})$/i.exec(input);
  if (short) return `#${short[1].split("").map(part => part + part).join("")}`.toLowerCase();
  const full = /^#([0-9a-f]{6})$/i.exec(input);
  return full ? `#${full[1].toLowerCase()}` : fallback;
}

function hexToRgb(hex) {
  const value = normalizeHexColor(hex).slice(1);
  return {
    r: Number.parseInt(value.slice(0, 2), 16),
    g: Number.parseInt(value.slice(2, 4), 16),
    b: Number.parseInt(value.slice(4, 6), 16)
  };
}

function mixHex(base, target, amount = 0.2) {
  const a = hexToRgb(base);
  const b = hexToRgb(target);
  const mix = channel => Math.round(channel[0] + (channel[1] - channel[0]) * clamp(amount, 0, 1));
  return `#${[mix([a.r, b.r]), mix([a.g, b.g]), mix([a.b, b.b])].map(value => value.toString(16).padStart(2, "0")).join("")}`;
}

function accentTextColor(hex) {
  const { r, g, b } = hexToRgb(hex);
  const linear = [r, g, b].map(value => {
    const channel = value / 255;
    return channel <= 0.03928 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
  });
  const luminance = 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2];
  return luminance > 0.48 ? "#07101f" : "#ffffff";
}

function appearanceLabel(value) {
  return ({ system: "System", dark: "Dunkel", light: "Hell" })[normalizeAppearance(value)];
}

function accentLabel(value) {
  const normalized = normalizeHexColor(value);
  return ACCENT_PRESETS.find(preset => preset.color === normalized)?.name || "Eigene Farbe";
}

function formatNumber(value, digits = 0) {
  return new Intl.NumberFormat("de-DE", { maximumFractionDigits: digits }).format(Number(value) || 0);
}

function formatWeight(value, unit = "kg") {
  const numeric = Number(value) || 0;
  const converted = unit === "lb" ? numeric * 2.2046226218 : numeric;
  return `${formatNumber(converted, converted % 1 ? 1 : 0)} ${unit}`;
}

function fromDisplayWeight(value, unit = "kg") {
  return unit === "lb" ? Number(value) / 2.2046226218 : Number(value);
}

function toDisplayWeight(value, unit = "kg") {
  return unit === "lb" ? Number(value) * 2.2046226218 : Number(value);
}

function validDate(input, fallback = null) {
  const date = input instanceof Date ? new Date(input.getTime()) : new Date(input);
  if (Number.isFinite(date.getTime())) return date;
  if (fallback == null) return null;
  const fallbackDate = fallback instanceof Date ? new Date(fallback.getTime()) : new Date(fallback);
  return Number.isFinite(fallbackDate.getTime()) ? fallbackDate : null;
}

function localDateKey(input = new Date()) {
  const date = validDate(input);
  if (!date) return "";
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function startOfDay(input = new Date()) {
  const date = validDate(input, new Date(0));
  date.setHours(0, 0, 0, 0);
  return date;
}

function startOfWeek(input = new Date()) {
  const date = startOfDay(input);
  date.setDate(date.getDate() - ((date.getDay() + 6) % 7));
  return date;
}

function daysBetween(later, earlier) {
  const laterDate = validDate(later);
  const earlierDate = validDate(earlier);
  if (!laterDate || !earlierDate) return Number.NaN;
  return Math.round((startOfDay(laterDate) - startOfDay(earlierDate)) / 86_400_000);
}

function formatDate(input, options = { day: "2-digit", month: "short" }) {
  const date = validDate(input);
  if (!date) return "Unbekannt";
  try { return new Intl.DateTimeFormat("de-DE", options).format(date); }
  catch { return "Unbekannt"; }
}

function relativeDate(input) {
  const date = validDate(input);
  if (!date) return "Unbekannt";
  const difference = daysBetween(new Date(), date);
  if (difference === 0) return "Heute";
  if (difference === 1) return "Gestern";
  if (difference > 1 && difference < 7) return `Vor ${difference} Tagen`;
  return formatDate(date, { day: "2-digit", month: "short", year: "numeric" });
}

function formatDuration(seconds) {
  const safe = Math.max(0, Math.floor(Number(seconds) || 0));
  const hours = Math.floor(safe / 3600);
  const minutes = Math.floor((safe % 3600) / 60);
  const rest = safe % 60;
  return hours > 0
    ? `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(rest).padStart(2, "0")}`
    : `${String(minutes).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

function normalizeRestSeconds(value, fallback = 120) {
  const numeric = Number(value);
  const candidate = Number.isFinite(numeric) ? Math.round(numeric) : Number(fallback);
  return clamp(candidate, MIN_REST_SECONDS, MAX_REST_SECONDS);
}

function splitRestSeconds(value) {
  const total = normalizeRestSeconds(value);
  return { minutes: Math.floor(total / 60), seconds: total % 60 };
}

function getInitials(name) {
  return String(name || "UP").split(/\s+/).filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase();
}

function epleyOneRepMax(weightKg, reps) {
  const weight = Number(weightKg) || 0;
  const repetitions = Number(reps) || 0;
  return weight <= 0 || repetitions <= 0 ? 0 : weight * (1 + Math.min(repetitions, 30) / 30);
}

function effectiveLoad(exercise, weightKg, bodyweightKg) {
  const weight = Number(weightKg) || 0;
  const bodyweight = Number(bodyweightKg) || 0;
  if (exercise?.bodyweightMode === "added") return weight + bodyweight;
  if (exercise?.bodyweightMode === "bodyweight") return bodyweight + weight;
  if (exercise?.bodyweightMode === "bodyweight-fraction") return bodyweight * (exercise.bodyweightFraction || 0.65) + weight;
  return weight;
}

function scoreLift(lift, bodyweightKg) {
  const exercise = lift.exercise || exerciseIndex.get(lift.exerciseId) || {};
  if (exercise.rankable === false || exercise.tracking === "time") return 0;
  const bodyweight = clamp(bodyweightKg, 30, 250) || 75;
  const oneRM = epleyOneRepMax(effectiveLoad(exercise, lift.weightKg ?? lift.weight, bodyweight), lift.reps);
  const reference = Math.max(1, Number(exercise.reference1RMKg || lift.reference1RMKg || 25));
  const exponent = Number(exercise.bodyweightExponent ?? 0.3);
  const adjustment = (75 / bodyweight) ** exponent;
  return Math.max(0, Math.round((oneRM / reference) * 350 * adjustment));
}

function rankFromScore(rawScore) {
  const score = Math.max(0, Math.round(Number(rawScore) || 0));
  const index = Math.min(RANKS.length - 1, Math.floor(score / 100));
  const current = RANKS[index];
  const next = RANKS[index + 1] || null;
  const lp = current.key === "olympian" ? Math.max(0, score - index * 100) : score - index * 100;
  const division = current.key === "olympian" ? "" : lp < 34 ? "III" : lp < 67 ? "II" : "I";
  return {
    key: current.key,
    name: current.name,
    color: current.color,
    index,
    score,
    lp,
    division,
    next,
    progress: next ? Math.min(1, lp / 100) : 1
  };
}

function aggregateGymScore(scores) {
  const ranked = scores.filter(score => score > 0).sort((a, b) => b - a).slice(0, 12);
  if (!ranked.length) return 0;
  let weighted = 0;
  let divisor = 0;
  ranked.forEach((score, index) => {
    const weight = 1 / (index + 1) ** 0.36;
    weighted += score * weight;
    divisor += weight;
  });
  return Math.round(weighted / divisor + Math.min(72, ranked.length * 6));
}

function workoutDate(workout) {
  return validDate(workout?.endedAt || workout?.date || workout?.startedAt) || new Date(0);
}

function getCurrentStreak(workouts) {
  const uniqueDates = [...new Set(workouts.map(workout => localDateKey(workoutDate(workout))).filter(Boolean))]
    .map(key => new Date(`${key}T12:00:00`))
    .sort((a, b) => a - b);
  if (!uniqueDates.length) return 0;
  const last = uniqueDates.at(-1);
  if (daysBetween(new Date(), last) > 3) return 0;
  let sequenceStart = last;
  for (let index = uniqueDates.length - 2; index >= 0; index -= 1) {
    if (daysBetween(sequenceStart, uniqueDates[index]) <= 3) sequenceStart = uniqueDates[index];
    else break;
  }
  return daysBetween(last, sequenceStart) + 1;
}

function collectBestLifts(workouts, bodyweightKg) {
  const best = new Map();
  for (const workout of workouts) {
    for (const lift of workout.bestLifts || []) {
      const normalized = {
        exerciseId: lift.exerciseId,
        name: lift.name || exerciseIndex.get(lift.exerciseId)?.name || "Übung",
        muscle: lift.muscle || exerciseIndex.get(lift.exerciseId)?.muscle || "Sonstiges",
        weightKg: Number(lift.weightKg ?? lift.weight) || 0,
        reps: Number(lift.reps) || 0,
        achievedAt: lift.achievedAt || workout.endedAt || workout.date,
        workoutId: workout.id,
        exercise: lift.exercise || null,
        reference1RMKg: lift.reference1RMKg || null,
        bodyweightExponent: lift.bodyweightExponent ?? null,
        bodyweightMode: lift.bodyweightMode || null
      };
      const score = scoreLift(normalized, workout.bodyweightKg || bodyweightKg);
      const previous = best.get(normalized.exerciseId);
      if (!previous || score > previous.score) best.set(normalized.exerciseId, { ...normalized, score });
    }
  }
  return [...best.values()]
    .map(lift => ({ ...lift, rank: rankFromScore(lift.score) }))
    .sort((a, b) => b.score - a.score);
}

function getMuscleStatuses(exerciseRanks) {
  return Object.fromEntries(MUSCLE_GROUPS.map(group => {
    const matching = exerciseRanks.filter(item => group.muscles.includes(item.muscle));
    const scores = matching.map(item => item.score).sort((a, b) => b - a).slice(0, 4);
    const score = scores.length ? Math.round(sum(scores.map((value, index) => value / (index + 1) ** 0.25)) / sum(scores.map((_, index) => 1 / (index + 1) ** 0.25))) : 0;
    return [group.key, {
      group,
      score,
      rank: rankFromScore(score),
      exerciseCount: matching.length,
      best: matching[0] || null,
      exercises: matching
    }];
  }));
}

function getMetrics(state) {
  const workouts = [...(state.workouts || [])].sort((a, b) => workoutDate(b) - workoutDate(a));
  const totalXp = Math.max(0, Number(state.profile?.legacyXp || 0)) + sum(workouts.map(workout => workout.xp));
  const weekStart = startOfWeek();
  const weeklyXp = sum(workouts.filter(workout => workoutDate(workout) >= weekStart).map(workout => workout.xp));
  const weeklyWorkouts = workouts.filter(workout => workoutDate(workout) >= weekStart);
  const volumeKg = sum(workouts.map(workout => workout.volumeKg ?? workout.volume));
  const exerciseRanks = collectBestLifts(workouts, state.profile.bodyweightKg);
  const gymScore = aggregateGymScore(exerciseRanks.map(item => item.score));
  const rank = rankFromScore(gymScore);
  const muscleStatuses = getMuscleStatuses(exerciseRanks);
  const streak = getCurrentStreak(workouts);
  const level = Math.floor(totalXp / 600) + 1;
  const levelXp = totalXp % 600;
  const prs = workouts.flatMap(workout => workout.prs || []);
  const recentPr = prs.sort((a, b) => new Date(b.achievedAt || 0) - new Date(a.achievedAt || 0))[0] || null;
  return {
    workouts,
    totalXp,
    weeklyXp,
    weeklyWorkouts,
    volumeKg,
    exerciseRanks,
    gymScore,
    rank,
    muscleStatuses,
    streak,
    level,
    levelXp,
    levelProgress: levelXp / 600,
    recentPr,
    eggs: Number(state.profile.eggs || 0)
  };
}

class StateRepository {
  constructor() {
    this.db = null;
    this.fallback = false;
    this.memory = new Map();
  }

  async open() {
    if (!("indexedDB" in window)) {
      this.fallback = true;
      return;
    }
    try {
      this.db = await new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);
        request.onupgradeneeded = () => {
          const database = request.result;
          if (!database.objectStoreNames.contains(DB_STORE)) database.createObjectStore(DB_STORE);
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    } catch {
      this.fallback = true;
    }
  }

  async get(accountKey) {
    const key = `state:${accountKey}`;
    const fallbackRead = () => {
      if (this.memory.has(key)) return deepClone(this.memory.get(key));
      try {
        const value = JSON.parse(safeStorageGet(`${DB_NAME}:${key}`) || "null");
        if (value) this.memory.set(key, deepClone(value));
        return value;
      } catch {
        return null;
      }
    };
    if (this.fallback || !this.db) return fallbackRead();
    try {
      const value = await new Promise((resolve, reject) => {
        const transaction = this.db.transaction(DB_STORE, "readonly");
        const request = transaction.objectStore(DB_STORE).get(key);
        request.onsuccess = () => resolve(request.result || null);
        request.onerror = () => reject(request.error);
        transaction.onabort = () => reject(transaction.error || new Error("IndexedDB-Lesevorgang abgebrochen"));
      });
      if (value) this.memory.set(key, deepClone(value));
      return value;
    } catch {
      this.fallback = true;
      return fallbackRead();
    }
  }

  async set(accountKey, state) {
    const key = `state:${accountKey}`;
    const snapshot = deepClone(state);
    this.memory.set(key, snapshot);
    const serialized = JSON.stringify(snapshot);
    const fallbackWrite = () => {
      // An in-memory copy keeps the current session usable even if storage is denied.
      safeStorageSet(`${DB_NAME}:${key}`, serialized);
      return true;
    };
    if (this.fallback || !this.db) return fallbackWrite();
    try {
      await new Promise((resolve, reject) => {
        const transaction = this.db.transaction(DB_STORE, "readwrite");
        transaction.objectStore(DB_STORE).put(snapshot, key);
        transaction.oncomplete = resolve;
        transaction.onerror = () => reject(transaction.error);
        transaction.onabort = () => reject(transaction.error || new Error("IndexedDB-Speichervorgang abgebrochen"));
      });
      return true;
    } catch {
      this.fallback = true;
      return fallbackWrite();
    }
  }

  async getAll() {
    const accounts = Object.keys(config.allowedAccounts || {});
    const entries = await Promise.all(accounts.map(async account => [account, await this.get(account)]));
    return Object.fromEntries(entries.filter(([, value]) => value));
  }
}

const repository = new StateRepository();

const WEEKDAYS = ["So", "Mo", "Di", "Mi", "Do", "Fr", "Sa"];
const WEEKDAY_LONG = ["Sonntag", "Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag", "Samstag"];
const SET_TYPE_LABELS = { warmup: "W", normal: "N", drop: "D", failure: "F" };
const SET_TYPE_NAMES = { warmup: "Aufwärmen", normal: "Normal", drop: "Dropsatz", failure: "Bis Versagen" };
const EXERCISE_EQUIPMENT = ["Langhantel", "Kurzhantel", "SZ-Stange", "Kabelzug", "Maschine", "Plate-loaded Maschine", "Smith Machine", "Körpergewicht", "Zusatzgewicht", "Gewichtsweste", "Kettlebell", "Trap Bar", "Safety-Bar", "Landmine", "Belt Squat", "Schlitten", "Widerstandsband", "TRX / Ringe", "Medizinball", "Gymnastikball", "GHD", "Ab Wheel", "Handgripper", "Wrist Roller", "Slider", "Springseil", "Gewichtsscheibe", "Sonstiges"];
const MUSCLE_COLORS = Object.fromEntries(MUSCLE_GROUPS.map((group, index) => [group.muscles[0] || group.name, ["#b78cff", "#ff6f59", "#ff9f43", "#ff5d7d", "#d8a15d", "#59d6c4", "#f48b6a", "#f3c65b", "#6c9cff", "#45b7e8", "#7e8da8", "#e98dc6", "#ef8f63", "#7dd6f4"][index] || "#ff6b4a"]));

function defaultReferenceForMuscle(muscle) {
  return ({
    "Brust": 75, "Schultern": 55, "Bizeps": 40, "Trizeps": 45, "Unterarme": 35,
    "Core": 50, "Adduktoren": 80, "Quadrizeps": 120, "Oberer Rücken": 95, "Lat": 90,
    "Unterer Rücken": 120, "Gesäß": 130, "Beinbeuger": 95, "Waden": 100
  })[muscle] || 50;
}

function resolveAccountKey() {
  const allowed = Object.keys(config.allowedAccounts || {});
  const params = new URLSearchParams(location.search);
  const requested = config.accountKey || params.get("account") || safeStorageGet("uprank-active-account");
  const accountKey = allowed.includes(requested) ? requested : allowed[0] || "johannes";
  safeStorageSet("uprank-active-account", accountKey);
  return accountKey;
}

function profileDefaults(accountKey) {
  const configured = config.allowedAccounts?.[accountKey] || {};
  return {
    name: configured.name || "Athlet",
    handle: configured.handle || `@${accountKey}`,
    location: configured.location || "",
    email: configured.email || "",
    avatar: "",
    bodyweightKg: 75,
    unit: "kg",
    eggs: 0,
    legacyXp: 0,
    bodyProfile: "unspecified",
    goal: "Stärker werden"
  };
}

function rf78LockJohannesCoins(state, accountKey = state?.accountKey) {
  // RANKFORGE 8.1: the provisional 999-coin preview is removed. Coins are earned and spent normally.
  return state;
}

function initialState(accountKey) {
  return {
    schemaVersion: SCHEMA_VERSION,
    appVersion: APP_VERSION,
    version: 1,
    accountKey,
    updatedAt: new Date().toISOString(),
    profile: profileDefaults(accountKey),
    settings: {
      appearance: "dark",
      accentColor: DEFAULT_ACCENT_COLOR,
      defaultRestSeconds: 120,
      autoStartRest: true,
      workoutTimerEnabled: true,
      restNotifications: true,
      weekStartsMonday: true,
      sound: true,
      haptics: true,
      autoSync: false
    },
    routines: deepClone(ROUTINE_BLUEPRINTS).map(routine => ({ ...routine, isCustom: false })),
    customExercises: [],
    workouts: [],
    draft: null,
    cachedMetrics: null,
    rewards: { unlocked: [], equipped: { profileFrame: "default", rankGlow: "default" } },
    challenges: { claims: {} },
    reminders: { enabled: false, time: "18:00", days: [1, 3, 5], lastNotifiedKey: "" },
    security: { pinEnabled: false, pinHash: "", locked: false },
    sync: { revision: 0, dirty: false, lastSyncedAt: null, tombstones: { workouts: {}, routines: {}, customExercises: {} } },
    onboardingComplete: false
  };
}

function normalizeSet(set = {}, index = 0) {
  const weightKg = clamp(Number(set.weightKg ?? set.weight ?? set.previousWeight ?? 0), 0, MAX_SET_WEIGHT_KG);
  const reps = clamp(Math.round(Number(set.reps ?? set.previousReps ?? 0)), 0, MAX_SET_REPS);
  return {
    id: String(set.id || uid(`set-${index + 1}`)),
    weightKg,
    reps,
    previousWeightKg: clamp(Number(set.previousWeightKg ?? set.previousWeight ?? weightKg), 0, MAX_SET_WEIGHT_KG),
    previousReps: clamp(Math.round(Number(set.previousReps ?? reps)), 0, MAX_SET_REPS),
    type: ["warmup", "normal", "drop", "failure"].includes(set.type) ? set.type : "normal",
    done: Boolean(set.done),
    rir: set.rir == null || set.rir === "" ? null : clamp(Math.round(Number(set.rir)), 0, 10),
    rpe: set.rpe == null || set.rpe === "" ? null : clamp(Number(set.rpe), 1, 10),
    tempo: String(set.tempo || "").slice(0, 15),
    durationSeconds: clamp(Number(set.durationSeconds || 0), 0, MAX_DURATION_SECONDS),
    distanceMeters: clamp(Number(set.distanceMeters || 0), 0, MAX_DISTANCE_METERS),
    assistanceKg: clamp(Number(set.assistanceKg || 0), 0, MAX_SET_WEIGHT_KG),
    side: ["both", "left", "right"].includes(set.side) ? set.side : "both",
    pain: clamp(Math.round(Number(set.pain || 0)), 0, 10),
    note: String(set.note || "").slice(0, 500),
    completedAt: set.completedAt || null,
    restTakenSeconds: clamp(Number(set.restTakenSeconds || 0), 0, MAX_DURATION_SECONDS),
    updatedAt: set.updatedAt || null
  };
}

function normalizeDraftExercise(item = {}, index = 0) {
  const base = exerciseIndex.get(item.exerciseId || item.id) || {};
  return {
    id: String(item.instanceId || item.id || uid(`exercise-${index + 1}`)),
    exerciseId: String(item.exerciseId || item.id || base.id || uid("custom")),
    name: String(item.name || base.name || "Übung").slice(0, 90),
    muscle: item.muscle || base.muscle || "Sonstiges",
    color: item.color || base.color || "#ff6b4a",
    equipment: item.equipment || base.equipment || "Sonstiges",
    rankable: item.rankable ?? base.rankable ?? true,
    bodyweightMode: item.bodyweightMode || base.bodyweightMode || "none",
    bodyweightExponent: Number(item.bodyweightExponent ?? base.bodyweightExponent ?? 0.3),
    reference1RMKg: Number(item.reference1RMKg ?? base.reference1RMKg ?? 25),
    referenceManual: item.referenceManual ?? base.referenceManual ?? false,
    rankCalibration: item.rankCalibration || base.rankCalibration || "estimated",
    executionMode: item.executionMode === "unilateral" ? "unilateral" : (base.executionMode === "unilateral" ? "unilateral" : "bilateral"),
    tracking: ["weight-reps", "time", "distance"].includes(item.tracking || base.tracking) ? (item.tracking || base.tracking) : "weight-reps",
    secondaryMuscles: Array.isArray(item.secondaryMuscles || base.secondaryMuscles) ? [...new Set(item.secondaryMuscles || base.secondaryMuscles)].slice(0, 5) : [],
    restSeconds: normalizeRestSeconds(item.restSeconds ?? base.defaultRestSeconds ?? 120),
    notes: String(item.notes || "").slice(0, 2000),
    supersetGroup: String(item.supersetGroup || ""),
    discomfort: Boolean(item.discomfort),
    targetMinReps: clamp(Math.round(Number(item.targetMinReps ?? base.targetMinReps ?? 6)), 1, 100),
    targetMaxReps: clamp(Math.round(Number(item.targetMaxReps ?? base.targetMaxReps ?? 12)), 1, 100),
    progressionStepKg: Math.max(0.25, Number(item.progressionStepKg ?? base.progressionStepKg ?? (["Quadrizeps", "Gesäß", "Beinbeuger", "Unterer Rücken", "Adduktoren", "Waden"].includes(item.muscle || base.muscle) ? 5 : 2.5)) || 2.5),
    sets: (item.sets || base.defaultSets || [{ weightKg: 0, reps: 0, type: "normal" }]).slice(0, MAX_SETS_PER_EXERCISE).map(normalizeSet)
  };
}

function normalizeCustomExercise(item = {}, index = 0) {
  const validMuscles = new Set(MUSCLE_GROUPS.flatMap(group => group.muscles));
  const muscle = validMuscles.has(item.muscle) ? item.muscle : (MUSCLE_GROUPS[0]?.muscles?.[0] || "Schultern");
  const equipment = EXERCISE_EQUIPMENT.includes(item.equipment) ? item.equipment : "Sonstiges";
  const defaultSets = Array.isArray(item.defaultSets) && item.defaultSets.length
    ? item.defaultSets.slice(0, MAX_SETS_PER_EXERCISE).map(set => ({
        weightKg: clamp(Number(set.weightKg ?? set.weight ?? 0), 0, MAX_SET_WEIGHT_KG),
        reps: clamp(Math.round(Number(set.reps) || 10), 1, MAX_SET_REPS),
        durationSeconds: clamp(Number(set.durationSeconds || 0), 0, MAX_DURATION_SECONDS),
        distanceMeters: clamp(Number(set.distanceMeters || 0), 0, MAX_DISTANCE_METERS),
        type: ["warmup", "normal", "drop", "failure"].includes(set.type) ? set.type : "normal"
      }))
    : Array.from({ length: 3 }, () => ({ weightKg: 0, reps: 10, type: "normal" }));
  const storedReference = Number(item.reference1RMKg || 0);
  const automaticReference = Number(defaultReferenceForMuscle(muscle) || 25);
  const referenceManual = item.referenceManual === true
    || (item.referenceManual == null && item.rankCalibration !== "estimated" && storedReference > 0 && Math.abs(storedReference - automaticReference) > 0.25);
  return {
    id: String(item.id || uid(`custom-${index + 1}`)),
    name: String(item.name || `Eigene Übung ${index + 1}`).trim().slice(0, 90),
    muscle,
    color: item.color || MUSCLE_COLORS[muscle] || "#ff6b4a",
    equipment,
    rankable: item.rankable !== false,
    bodyweightMode: item.bodyweightMode || (equipment === "Körpergewicht" ? "bodyweight" : "none"),
    bodyweightExponent: Number(item.bodyweightExponent ?? 0.3),
    reference1RMKg: Math.max(1, Number(item.reference1RMKg) || defaultReferenceForMuscle(muscle)),
    referenceManual,
    rankCalibration: referenceManual ? "calibrated" : "estimated",
    executionMode: item.executionMode === "unilateral" ? "unilateral" : "bilateral",
    defaultRestSeconds: normalizeRestSeconds(item.defaultRestSeconds ?? 120),
    tracking: ["weight-reps", "time", "distance"].includes(item.tracking) ? item.tracking : "weight-reps",
    secondaryMuscles: Array.isArray(item.secondaryMuscles) ? [...new Set(item.secondaryMuscles)].filter(value => value !== muscle).slice(0, 5) : [],
    instructions: String(item.instructions || "").slice(0, 1200),
    tips: Array.isArray(item.tips) ? item.tips.map(String).slice(0, 6) : [],
    defaultSets,
    createdAt: item.createdAt || new Date().toISOString(),
    updatedAt: item.updatedAt || item.createdAt || new Date().toISOString(),
    isCustom: true
  };
}

// X5.9: a plain greeting instead of a slogan.
function homeGreeting(now = new Date()) {
  const hour = now.getHours();
  return hour < 5 ? "Gute Nacht" : hour < 11 ? "Guten Morgen" : hour < 18 ? "Hallo" : "Guten Abend";
}

function homeDateLine(now = new Date()) {
  return `${WEEKDAY_LONG[now.getDay()]}, ${now.getDate()}. ${["Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"][now.getMonth()]}`;
}

function normalizeRoutine(routine = {}, index = 0) {
  const id = String(routine.id || uid(`routine-${index + 1}`));
  const isBuiltIn = ROUTINE_BLUEPRINTS.some(blueprint => blueprint.id === id);
  return {
    id,
    title: String(routine.title || routine.name || `Training ${index + 1}`),
    summary: String(routine.summary || "Eigenes Training"),
    scheduleDays: Array.isArray(routine.scheduleDays) ? [...new Set(routine.scheduleDays.map(Number).filter(day => day >= 0 && day <= 6))] : [],
    isCustom: routine.isCustom == null ? !isBuiltIn : Boolean(routine.isCustom),
    isDraft: Boolean(routine.isDraft),
    createdAt: routine.createdAt || null,
    updatedAt: routine.updatedAt || null,
    exercises: Array.isArray(routine.exercises) ? routine.exercises.slice(0, MAX_ROUTINE_EXERCISES).map(item => ({
      exerciseId: String(item.exerciseId || item.id),
      restSeconds: normalizeRestSeconds(item.restSeconds ?? 120),
      supersetGroup: String(item.supersetGroup || ""),
      targetMinReps: clamp(Math.round(Number(item.targetMinReps || 6)), 1, 100),
      targetMaxReps: clamp(Math.round(Number(item.targetMaxReps || 12)), 1, 100),
      progressionStepKg: Math.max(0.25, Number(item.progressionStepKg || 2.5) || 2.5),
      sets: (item.sets || []).slice(0, MAX_SETS_PER_EXERCISE).map(set => ({
        weightKg: clamp(Number(set.weightKg ?? set.weight ?? (Array.isArray(set) ? set[0] : 0)), 0, MAX_SET_WEIGHT_KG),
        reps: clamp(Math.round(Number(set.reps ?? (Array.isArray(set) ? set[1] : 0))), 1, MAX_SET_REPS),
        type: ["warmup", "normal", "drop", "failure"].includes(set.type) ? set.type : "normal"
      }))
    })) : []
  };
}

function normalizeWorkout(workout = {}, index = 0) {
  const now = new Date();
  const endedDate = validDate(workout.endedAt || workout.date, now) || now;
  const startedDate = validDate(workout.startedAt, endedDate) || endedDate;
  const endedAt = endedDate.toISOString();
  const startedAt = startedDate.toISOString();
  return {
    id: String(workout.id || uid(`workout-${index + 1}`)),
    name: String(workout.name || workout.title || "Training").slice(0, 90),
    routineId: workout.routineId || null,
    quickWorkout: Boolean(workout.quickWorkout),
    startedAt,
    endedAt,
    durationSeconds: clamp(Number(workout.durationSeconds ?? workout.duration ?? Math.max(0, (endedDate - startedDate) / 1000)), 0, MAX_DURATION_SECONDS),
    bodyweightKg: clamp(Number(workout.bodyweightKg ?? workout.bodyWeight ?? 75), 30, 250) || 75,
    notes: String(workout.notes || "").slice(0, 4000),
    setsCount: clamp(Math.round(Number(workout.setsCount ?? workout.sets ?? 0)), 0, MAX_WORKOUT_EXERCISES * MAX_SETS_PER_EXERCISE),
    volumeKg: clamp(Number(workout.volumeKg ?? workout.volume ?? 0), 0, 1_000_000_000),
    xp: clamp(Math.round(Number(workout.xp || 0)), 0, 10_000_000),
    eggs: clamp(Math.round(Number(workout.eggs || 0)), 0, 1_000_000),
    exercises: Array.isArray(workout.exercises) ? workout.exercises.slice(0, MAX_WORKOUT_EXERCISES).map(normalizeDraftExercise) : [],
    bestLifts: Array.isArray(workout.bestLifts) ? workout.bestLifts.slice(0, 250).map(lift => ({
      exerciseId: String(lift.exerciseId || lift.id),
      name: String(lift.name || exerciseIndex.get(lift.exerciseId || lift.id)?.name || "Übung").slice(0, 90),
      muscle: lift.muscle || exerciseIndex.get(lift.exerciseId || lift.id)?.muscle || "Sonstiges",
      weightKg: clamp(Number(lift.weightKg ?? lift.weight ?? 0), 0, MAX_SET_WEIGHT_KG),
      reps: clamp(Math.round(Number(lift.reps || 0)), 0, MAX_SET_REPS),
      achievedAt: (validDate(lift.achievedAt, endedDate) || endedDate).toISOString(),
      reference1RMKg: Number(lift.reference1RMKg || 0) || undefined,
      bodyweightMode: lift.bodyweightMode || undefined,
      bodyweightExponent: lift.bodyweightExponent ?? undefined,
      exercise: lift.exercise || undefined
    })) : [],
    prs: Array.isArray(workout.prs) ? workout.prs.slice(0, 100) : [],
    rank: workout.rank || null,
    rankBefore: workout.rankBefore || null,
    createdAt: (validDate(workout.createdAt || workout.startedAt, startedDate) || startedDate).toISOString(),
    updatedAt: (validDate(workout.updatedAt, endedDate) || endedDate).toISOString(),
    restSecondsTotal: clamp(Number(workout.restSecondsTotal || 0), 0, MAX_DURATION_SECONDS)
  };
}

function normalizeState(raw, accountKey) {
  const base = initialState(accountKey);
  if (!raw || typeof raw !== "object") return rf78LockJohannesCoins(base, accountKey);
  const normalized = {
    ...base,
    ...raw,
    schemaVersion: SCHEMA_VERSION,
    appVersion: APP_VERSION,
    accountKey,
    profile: { ...base.profile, ...(raw.profile || {}) },
    settings: { ...base.settings, ...(raw.settings || {}) },
    routines: Array.isArray(raw.routines) ? raw.routines.slice(0, MAX_STORED_ROUTINES).map(normalizeRoutine).filter(routine => !routine.isDraft) : base.routines,
    customExercises: Array.isArray(raw.customExercises) ? raw.customExercises.slice(0, MAX_CUSTOM_EXERCISES).map(normalizeCustomExercise) : [],
    workouts: Array.isArray(raw.workouts) ? raw.workouts.slice(0, MAX_STORED_WORKOUTS).map(normalizeWorkout) : [],
    draft: raw.draft ? {
      id: String(raw.draft.id || uid("draft")),
      routineId: raw.draft.routineId || null,
      quickWorkout: Boolean(raw.draft.quickWorkout),
      editingWorkoutId: raw.draft.editingWorkoutId || null,
      originalStartedAt: raw.draft.originalStartedAt || null,
      originalEndedAt: raw.draft.originalEndedAt || null,
      originalDurationSeconds: Number(raw.draft.originalDurationSeconds || 0) || 0,
      restTimerEnabled: raw.draft.restTimerEnabled !== false,
      name: String(raw.draft.name || "Freies Training").slice(0, 90),
      startedAt: (validDate(raw.draft.startedAt, new Date()) || new Date()).toISOString(),
      notes: String(raw.draft.notes || "").slice(0, 4000),
      exercises: Array.isArray(raw.draft.exercises) ? raw.draft.exercises.slice(0, MAX_WORKOUT_EXERCISES).map(normalizeDraftExercise) : []
    } : null
  };
  normalized.profile.bodyweightKg = clamp(normalized.profile.bodyweightKg, 30, 250) || 75;
  normalized.profile.unit = normalized.profile.unit === "lb" ? "lb" : "kg";
  normalized.settings.appearance = normalizeAppearance(normalized.settings.appearance);
  normalized.settings.accentColor = normalizeHexColor(normalized.settings.accentColor);
  normalized.settings.defaultRestSeconds = normalizeRestSeconds(normalized.settings.defaultRestSeconds, 120);
  normalized.settings.autoStartRest = normalized.settings.autoStartRest !== false;
  normalized.settings.workoutTimerEnabled = normalized.settings.workoutTimerEnabled !== false;
  normalized.settings.restNotifications = normalized.settings.restNotifications !== false;
  normalized.routines.forEach(routine => routine.exercises.forEach(item => {
    item.restSeconds = normalizeRestSeconds(item.restSeconds, normalized.settings.defaultRestSeconds);
  }));
  if (normalized.draft) normalized.draft.exercises.forEach(exercise => {
    exercise.restSeconds = normalizeRestSeconds(exercise.restSeconds, normalized.settings.defaultRestSeconds);
  });
  const routineIds = new Set(normalized.routines.map(routine => routine.id));
  // X5.9: a deleted built-in workout (Push Day, Pull Day, ...) stays deleted.
  const deletedRoutines = raw.sync?.tombstones?.routines || {};
  ROUTINE_BLUEPRINTS.forEach((blueprint, blueprintIndex) => {
    if (!routineIds.has(blueprint.id) && !deletedRoutines[blueprint.id] && normalized.routines.length < MAX_STORED_ROUTINES) {
      normalized.routines.push(normalizeRoutine({ ...deepClone(blueprint), isCustom: false }, normalized.routines.length + blueprintIndex));
      routineIds.add(blueprint.id);
    }
  });
  return rf78LockJohannesCoins(normalized, accountKey);
}

function readLegacyState(accountKey) {
  const keys = [
    `uprank-training-state-v3:${accountKey}`,
    `uprank-training-state-v3-${accountKey}`,
    "uprank-training-state-v3",
    "uprank-training-state-v2",
    "uprank-training-state-v1"
  ];
  for (const key of keys) {
    try {
      const parsed = JSON.parse(safeStorageGet(key) || "null");
      if (!parsed || typeof parsed !== "object") continue;
      const migrated = initialState(accountKey);
      migrated.profile.bodyweightKg = clamp(parsed.bodyWeight ?? parsed.bodyweightKg ?? 75, 30, 250) || 75;
      migrated.profile.legacyXp = Math.max(0, Number(parsed.xp || 0));
      migrated.profile.eggs = Math.max(0, Number(parsed.eggs || 0));
      migrated.workouts = (parsed.history || parsed.workouts || []).map(normalizeWorkout);
      const workoutXp = sum(migrated.workouts.map(workout => workout.xp));
      migrated.profile.legacyXp = Math.max(0, migrated.profile.legacyXp - workoutXp);
      const active = parsed.activeWorkout || parsed.draft;
      if (active?.exercises?.length) {
        migrated.draft = {
          id: uid("draft"),
          routineId: active.routineId || null,
          quickWorkout: Boolean(active.quickWorkout),
          editingWorkoutId: null,
          name: active.name || "Training",
          startedAt: new Date(active.startedAt || Date.now()).toISOString(),
          notes: active.notes || "",
          exercises: active.exercises.map(normalizeDraftExercise)
        };
      }
      migrated.updatedAt = new Date().toISOString();
      return migrated;
    } catch {
      // Ignore invalid old browser state and try the next key.
    }
  }
  return null;
}

function allExercises(state) {
  const custom = (state.customExercises || []).map(normalizeCustomExercise);
  return custom.length ? EXERCISES.concat(custom) : EXERCISES;
}

function savedRoutines(state) {
  return (state.routines || []).filter(routine => !routine.isDraft);
}

function lookupExercise(state, id) {
  return exerciseIndex.get(id) || (state.customExercises || []).find(exercise => exercise.id === id) || null;
}

function getRoutineSetCount(routine) {
  return sum((routine?.exercises || []).map(item => item.sets?.length || 0));
}

function getNextRoutine(state, date = new Date()) {
  const routines = savedRoutines(state);
  if (!routines.length) return null;
  const today = date.getDay();
  const todayRoutine = routines.find(routine => routine.scheduleDays?.includes(today));
  if (todayRoutine) return { routine: todayRoutine, daysAway: 0 };
  for (let distance = 1; distance <= 7; distance += 1) {
    const day = (today + distance) % 7;
    const routine = routines.find(candidate => candidate.scheduleDays?.includes(day));
    if (routine) return { routine, daysAway: distance };
  }
  return { routine: routines[0], daysAway: 0 };
}

function previousSetForExercise(state, exerciseId, setIndex) {
  const workouts = [...(state.workouts || [])].sort((a, b) => workoutDate(b) - workoutDate(a));
  for (const workout of workouts) {
    const exercise = (workout.exercises || []).find(item => item.exerciseId === exerciseId);
    const set = exercise?.sets?.filter(item => item.done)[setIndex] || exercise?.sets?.[setIndex];
    if (set) return { weightKg: Number(set.weightKg || 0), reps: Number(set.reps || 0) };
  }
  return null;
}

function instantiateRoutine(state, routine, editingWorkoutId = null) {
  const exercises = (routine?.exercises || []).map((item, exerciseIndexPosition) => {
    const exercise = lookupExercise(state, item.exerciseId) || {
      id: item.exerciseId,
      name: "Unbekannte Übung",
      muscle: "Sonstiges",
      color: "#ff6b4a",
      equipment: "Sonstiges",
      defaultRestSeconds: 120,
      reference1RMKg: 25,
      rankable: true,
      bodyweightMode: "none",
      bodyweightExponent: 0.3
    };
    const templateSets = item.sets?.length ? item.sets : exercise.defaultSets;
    return normalizeDraftExercise({
      instanceId: uid(`exercise-${exerciseIndexPosition + 1}`),
      exerciseId: exercise.id,
      name: exercise.name,
      muscle: exercise.muscle,
      color: exercise.color,
      equipment: exercise.equipment,
      rankable: exercise.rankable,
      bodyweightMode: exercise.bodyweightMode,
      bodyweightExponent: exercise.bodyweightExponent,
      reference1RMKg: exercise.reference1RMKg,
      tracking: exercise.tracking,
      secondaryMuscles: exercise.secondaryMuscles,
      supersetGroup: item.supersetGroup,
      targetMinReps: item.targetMinReps,
      targetMaxReps: item.targetMaxReps,
      progressionStepKg: item.progressionStepKg,
      restSeconds: item.restSeconds ?? exercise.defaultRestSeconds ?? state.settings.defaultRestSeconds,
      sets: (templateSets || []).map((set, setIndex) => {
        const previous = previousSetForExercise(state, exercise.id, setIndex);
        const weightKg = previous?.weightKg ?? (Number(set.weightKg ?? set.weight ?? 0) || 0);
        const reps = previous?.reps ?? (Number(set.reps || 0) || 0);
        return {
          id: uid("set"),
          weightKg,
          reps,
          previousWeightKg: previous?.weightKg ?? weightKg,
          previousReps: previous?.reps ?? reps,
          durationSeconds: Number(set.durationSeconds || 0),
          distanceMeters: Number(set.distanceMeters || 0),
          type: set.type || "normal",
          done: false
        };
      })
    });
  });
  return {
    id: uid("draft"),
    routineId: routine?.id || null,
    quickWorkout: false,
    editingWorkoutId,
    name: routine?.title || "Freies Training",
    startedAt: new Date().toISOString(),
    notes: "",
    exercises
  };
}

function instantiateExercise(state, exerciseId) {
  const exercise = lookupExercise(state, exerciseId);
  if (!exercise) return null;
  return normalizeDraftExercise({
    instanceId: uid("exercise"),
    exerciseId: exercise.id,
    name: exercise.name,
    muscle: exercise.muscle,
    color: exercise.color,
    equipment: exercise.equipment,
    rankable: exercise.rankable,
    bodyweightMode: exercise.bodyweightMode,
    bodyweightExponent: exercise.bodyweightExponent,
    reference1RMKg: exercise.reference1RMKg,
    tracking: exercise.tracking,
    secondaryMuscles: exercise.secondaryMuscles,
    targetMinReps: exercise.targetMinReps,
    targetMaxReps: exercise.targetMaxReps,
    progressionStepKg: exercise.progressionStepKg,
    restSeconds: state.settings.defaultRestSeconds || exercise.defaultRestSeconds,
    sets: (exercise.defaultSets || [{ weightKg: 0, reps: 8 }, { weightKg: 0, reps: 8 }, { weightKg: 0, reps: 8 }]).map((set, setIndex) => {
      const previous = previousSetForExercise(state, exercise.id, setIndex);
      const weightKg = previous?.weightKg ?? Number(set.weightKg ?? set.weight ?? 0);
      const reps = previous?.reps ?? Number(set.reps || 0);
      return {
        id: uid("set"),
        weightKg,
        reps,
        previousWeightKg: previous?.weightKg ?? weightKg,
        previousReps: previous?.reps ?? reps,
        durationSeconds: Number(set.durationSeconds || 0),
        distanceMeters: Number(set.distanceMeters || 0),
        type: set.type || "normal",
        done: false
      };
    })
  });
}

function rankTitle(rank) {
  return `${rank.name}${rank.division ? ` ${rank.division}` : ""}`;
}

const RANK_KEYS = new Set(RANKS.map(rank => rank.key));

function rankKey(rank) {
  if (RANK_KEYS.has(rank?.key)) return rank.key;
  return RANKS.find(item => item.name.toLowerCase() === String(rank?.name || "").toLowerCase())?.key || "wood";
}

function rankAssetPath(rank) {
  const key = rankKey(rank);
  if (["platinum", "diamond", "champion", "titan"].includes(key)) {
    return `./assets/ranks/${key}-v9.2.0.png`;
  }
  return `./assets/ranks/${key}.webp`;
}

function rankMark(rank, compact = false) {
  const key = rankKey(rank);
  const division = rank?.division ? `<span class="rank-mark__division" aria-hidden="true">${escapeHtml(rank.division)}</span>` : "";
  return `<div class="rank-mark rank-mark--${escapeAttr(key)} ${compact ? "rank-mark--compact" : ""}" style="--rank-color:${escapeAttr(rank.color)}" role="img" aria-label="${escapeAttr(rankTitle(rank))}">
    <span class="rank-mark__halo" aria-hidden="true"></span>
    <img class="rank-mark__image" src="${escapeAttr(rankAssetPath(rank))}" width="256" height="256" alt="" decoding="async">
    ${division}
  </div>`;
}

function rankProgress(rank) {
  const nextName = rank.next?.name || "Maximalrang";
  return `<div class="rank-progress">
    <div class="rank-progress__labels"><strong>${formatNumber(rank.lp)} LP</strong><span>${rank.next ? `${100 - rank.lp} LP bis ${nextName}` : "Olympian erreicht"}</span></div>
    <div class="progress-track"><i style="width:${Math.round(rank.progress * 100)}%;--bar:${escapeAttr(rank.color)}"></i></div>
  </div>`;
}

function weekStrip(workouts) {
  const monday = startOfWeek();
  const completed = new Set(workouts.map(workout => localDateKey(workoutDate(workout))));
  return `<div class="week-strip">${Array.from({ length: 7 }, (_, index) => {
    const date = new Date(monday);
    date.setDate(monday.getDate() + index);
    const key = localDateKey(date);
    const isToday = key === localDateKey();
    return `<div class="week-day ${isToday ? "is-today" : ""} ${completed.has(key) ? "is-done" : ""}">
      <span>${WEEKDAYS[date.getDay()]}</span><strong>${date.getDate()}</strong><i></i>
    </div>`;
  }).join("")}</div>`;
}

function emptyState(iconName, title, text, action = "", label = "") {
  return `<div class="empty-state"><div class="empty-state__icon">${icon(iconName, 24)}</div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(text)}</p>${action ? `<button class="button button--secondary" data-action="${escapeAttr(action)}">${escapeHtml(label)}</button>` : ""}</div>`;
}

function muscleSvgGroup(key, paths, statuses, selected) {
  const status = statuses[key];
  const hasRank = Boolean(status?.score);
  const group = MUSCLE_GROUPS.find(item => item.key === key);
  const color = hasRank ? status.rank.color : rankFromScore(0).color; // X6.1: untrainiert = Holz
  const name = status?.group?.name || key;
  return `<g class="muscle-region muscle-region--${escapeAttr(key)} ${hasRank ? "has-rank" : "is-unranked"} ${selected === key ? "is-selected" : ""}" style="--muscle-color:${escapeAttr(color)}" data-action="select-muscle" data-muscle="${escapeAttr(key)}" role="button" tabindex="0" aria-label="${escapeAttr(name)}">${paths}</g>`;
}

function bodyMaskGroup(view, key, statuses, selected, pathData, interactive = true) {
  if (!pathData) return "";
  const status = statuses[key];
  const hasRank = Boolean(status?.score);
  const group = MUSCLE_GROUPS.find(item => item.key === key);
  const color = hasRank ? status.rank.color : rankFromScore(0).color; // X6.1: untrainiert = Holz
  const name = status?.group?.name || key;
  const safePath = escapeAttr(pathData);
  const interaction = interactive
    ? ` data-action="select-muscle" data-muscle="${escapeAttr(key)}" role="button" tabindex="0" aria-label="${escapeAttr(name)}"`
    : ` aria-hidden="true"`;
  return `<g class="muscle-region muscle-region--masked muscle-region--${escapeAttr(key)} ${hasRank ? "has-rank" : "is-unranked"} ${selected === key ? "is-selected" : ""}" style="--muscle-color:${escapeAttr(color)}"${interaction}>
    <path class="muscle-hit" d="${safePath}" fill-rule="evenodd" aria-hidden="true"/>
    <path class="muscle-fill" d="${safePath}" fill-rule="evenodd"/>
  </g>`;
}

function realisticBodyFigure(view, statuses, selected, options = {}) {
  const assets = bodygraphAssets;
  const width = Number(assets?.width || 118);
  const height = Number(assets?.height || 288);
  const baseSource = document.documentElement.dataset.theme === "light"
    ? (assets?.baseLight?.[view] || assets?.base?.[view])
    : assets?.base?.[view];
  const paths = assets?.paths?.[view] || {};
  const order = view === "front" ? FRONT_BODY_MUSCLES : BACK_BODY_MUSCLES;
  const label = options.hideLabel ? "" : `<span>${view === "front" ? "VORNE" : "HINTEN"}</span>`;
  const extraClass = options.className ? ` ${escapeAttr(options.className)}` : "";
  return `<div class="body-figure body-figure--realistic${extraClass}">${label}<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${view === "front" ? "Vorderseite" : "Rückseite"} des Muskelstatus">
    <image class="body-anatomy-base" href="${escapeAttr(baseSource)}" x="0" y="0" width="${width}" height="${height}" preserveAspectRatio="none" aria-hidden="true"/>
    ${order.map(key => bodyMaskGroup(view, key, statuses, selected, paths[key], options.interactive !== false)).join("")}
  </svg></div>`;
}

