  function rf81Equipped(app,reward) {
    const eq=app.state.rewards.equipped;
    return reward.type==='frame' ? eq.profileFrame===reward.id : reward.type==='effect' ? eq.rankGlow===reward.value : reward.type==='home' ? eq.homeSkin===reward.value : reward.type==='sound' ? eq.timerSound===reward.value : reward.type==='hud' ? eq.workoutHud===reward.value : reward.type==='body' ? eq.bodygraphFrame===reward.value : false;
  }
  function rf81Equip(app,reward) {
    const eq=app.state.rewards.equipped;
    if(reward.type==='frame')eq.profileFrame=reward.id;
    else if(reward.type==='effect')eq.rankGlow=reward.value;
    else if(reward.type==='home')eq.homeSkin=reward.value;
    else if(reward.type==='sound')eq.timerSound=reward.value;
    else if(reward.type==='hud')eq.workoutHud=reward.value;
    else if(reward.type==='body')eq.bodygraphFrame=reward.value;
    applyRf81Visuals(app);
  }
  function rf81Reset(app,type) {
    const eq=app.state.rewards.equipped;
    if(type==='frame')eq.profileFrame='default'; else if(type==='effect')eq.rankGlow='default'; else if(type==='home')eq.homeSkin='default'; else if(type==='sound')eq.timerSound='default'; else if(type==='hud')eq.workoutHud='default'; else if(type==='body')eq.bodygraphFrame='default';
    applyRf81Visuals(app);
  }
  function applyRf81Visuals(app) {
    if(!app?.state)return; const eq=app.state.rewards?.equipped||{}; const root=document.documentElement;
    root.dataset.rankEffect=eq.rankGlow||'default'; root.dataset.homeSkin=eq.homeSkin||'default'; root.dataset.workoutHud=eq.workoutHud||'default'; root.dataset.bodygraphFrame=eq.bodygraphFrame||'default'; root.dataset.coachingStyle=app.state.personalization?.coachingStyle||'balanced';
  }
