/* RANKFORGE 8.8.1 — accent workout card, collapsible rank lists and clean avatars */
(function installRankforge881(AppClass) {
  "use strict";
  if (!AppClass || AppClass.prototype.__rf881Installed) return;
  const proto = AppClass.prototype;
  proto.__rf881Installed = true;

  const previous = {
    init: proto.init,
    render: proto.render,
    renderHome: proto.renderHome,
    renderYourRank: proto.renderYourRank,
    renderBodygraph: proto.renderBodygraph,
    renderLeagues: proto.renderLeagues,
    handleClick: proto.handleClick,
    renderRf80WhatsNew: proto.renderRf80WhatsNew
  };

  const RF881_VERSION = "8.8.1";
  const SECTION_DEFAULTS = Object.freeze({
    exerciseRanks: false,
    muscleRanks: false,
    muscleColors: false,
    rankLadder: false
  });

  function ensure881(app) {
    if (!app?.state) return;
    app.state.settings ||= {};
    const raw = app.state.settings.collapsibleSections;
    const stored = raw && typeof raw === "object" ? raw : {};
    app.state.settings.collapsibleSections = {
      exerciseRanks: typeof stored.exerciseRanks === "boolean" ? stored.exerciseRanks : SECTION_DEFAULTS.exerciseRanks,
      muscleRanks: typeof stored.muscleRanks === "boolean" ? stored.muscleRanks : SECTION_DEFAULTS.muscleRanks,
      muscleColors: typeof stored.muscleColors === "boolean" ? stored.muscleColors : SECTION_DEFAULTS.muscleColors,
      rankLadder: typeof stored.rankLadder === "boolean" ? stored.rankLadder : SECTION_DEFAULTS.rankLadder
    };
    app.state.appVersion = RF881_VERSION;
  }

  function isOpen881(app, key) {
    ensure881(app);
    return Boolean(app.state.settings.collapsibleSections[key]);
  }

  function template881(html) {
    const template = document.createElement("template");
    template.innerHTML = String(html || "").trim();
    return template;
  }

  function makeToggle881({ key, title, detail, count, open, iconName = "chevronDown" }) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "rf881-collapsible__toggle";
    button.dataset.action = "rf881-toggle-section";
    button.dataset.section = key;
    button.setAttribute("aria-expanded", String(open));
    button.innerHTML = `<span class="rf881-collapsible__icon">${icon(iconName, 19)}</span><span class="rf881-collapsible__copy"><strong>${escapeHtml(title)}</strong><small>${escapeHtml(detail)}</small></span>${count != null ? `<b>${escapeHtml(String(count))}</b>` : ""}<span class="rf881-collapsible__chevron">${icon("chevronDown", 18)}</span>`;
    return button;
  }

  function collapseSection881(section, { key, title, detail, count, open, bodySelector = null, iconName = "chevronDown" }) {
    if (!section) return;
    section.classList.add("rf881-collapsible", open ? "is-open" : "is-collapsed");
    section.classList.remove(open ? "is-collapsed" : "is-open");

    let body = bodySelector ? section.querySelector(bodySelector) : null;
    if (!body) {
      body = document.createElement("div");
      body.className = "rf881-collapsible__body";
      const keep = new Set(Array.from(section.children).filter(node => node.classList?.contains("section-heading")));
      Array.from(section.children).filter(node => !keep.has(node)).forEach(node => body.append(node));
      section.append(body);
    } else {
      body.classList.add("rf881-collapsible__body");
    }
    body.hidden = !open;

    const oldToggle = section.querySelector(":scope > .rf881-collapsible__toggle");
    oldToggle?.remove();
    const toggle = makeToggle881({ key, title, detail, count, open, iconName });
    const heading = section.querySelector(":scope > .section-heading");
    if (heading) heading.after(toggle);
    else section.prepend(toggle);
  }

  proto.renderHome = function() {
    ensure881(this);
    return previous.renderHome.call(this)
      .replace("Bodygraph repariert", "Übersicht verbessert")
      .replace("Scharfe Figur · saubere Farben · keine Bildfehler", "Akzent-Workout · einklappbare Rankings");
  };

  proto.renderYourRank = function() {
    ensure881(this);
    const template = template881(previous.renderYourRank.call(this));
    const section = template.content.querySelector(".exercise-ranks");
    if (section) {
      const ranks = Array.isArray(this.metrics?.exerciseRanks) ? this.metrics.exerciseRanks : [];
      const best = ranks[0];
      const detail = best
        ? `Stärkste Übung: ${best.name} · ${rankTitle(best.rank)}`
        : "Deine stärksten Übungen erscheinen nach dem ersten Workout.";
      collapseSection881(section, {
        key: "exerciseRanks",
        title: "Alle Exercise Rankings",
        detail,
        count: ranks.length,
        open: isOpen881(this, "exerciseRanks"),
        iconName: "ranks"
      });
    }
    return template.innerHTML;
  };

  proto.renderBodygraph = function() {
    ensure881(this);
    const template = template881(previous.renderBodygraph.call(this));
    const muscleList = template.content.querySelector(".muscle-chip-list");
    if (muscleList && !muscleList.closest(".rf881-muscle-ranks")) {
      const open = isOpen881(this, "muscleRanks");
      const wrapper = document.createElement("section");
      wrapper.className = `rf881-muscle-ranks rf881-collapsible ${open ? "is-open" : "is-collapsed"}`;
      wrapper.append(makeToggle881({
        key: "muscleRanks",
        title: "Muskel-Ranks",
        detail: "Alle 14 Muskelgruppen und ihr aktueller Rang",
        count: MUSCLE_GROUPS.length,
        open,
        iconName: "ranks"
      }));
      const body = document.createElement("div");
      body.className = "rf881-collapsible__body";
      body.hidden = !open;
      muscleList.replaceWith(wrapper);
      body.append(muscleList);
      wrapper.append(body);
    }

    const section = template.content.querySelector(".rf80-muscle-key");
    if (section) {
      const grid = section.querySelector(".rf80-muscle-key__grid");
      section.innerHTML = "";
      const open = isOpen881(this, "muscleColors");
      section.className = `rf80-muscle-key rf881-collapsible ${open ? "is-open" : "is-collapsed"}`;
      section.append(makeToggle881({
        key: "muscleColors",
        title: "Farben der Muskelgruppen",
        detail: "14 eindeutige Basisfarben als Legende",
        count: MUSCLE_GROUPS.length,
        open,
        iconName: "palette"
      }));
      const body = document.createElement("div");
      body.className = "rf881-collapsible__body";
      body.hidden = !open;
      if (grid) body.append(grid);
      section.append(body);
    }
    return template.innerHTML;
  };

  proto.renderLeagues = function() {
    ensure881(this);
    const template = template881(previous.renderLeagues.call(this));
    const section = template.content.querySelector(".rank-ladder");
    if (section) {
      collapseSection881(section, {
        key: "rankLadder",
        title: "Komplette Rank Ladder",
        detail: `Aktuell: ${rankTitle(this.metrics.rank)} · 100 LP pro Rang`,
        count: RANKS.length,
        open: isOpen881(this, "rankLadder"),
        iconName: "trophy"
      });
    }
    return template.innerHTML;
  };

  proto.handleClick = async function(event) {
    const element = event.target?.closest?.("[data-action]");
    const action = element?.dataset?.action;
    if (action !== "rf881-toggle-section") return previous.handleClick.call(this, event);
    event.preventDefault();
    event.stopPropagation();
    ensure881(this);
    const key = String(element.dataset.section || "");
    if (!Object.prototype.hasOwnProperty.call(SECTION_DEFAULTS, key)) return;
    const nextOpen = !isOpen881(this, key);
    this.state.settings.collapsibleSections[key] = nextOpen;
    this.scheduleSave?.();
    this.render();
  };

  proto.render = function(...args) {
    if (this.state) ensure881(this);
    return previous.render.apply(this, args);
  };

  proto.renderRf80WhatsNew = function() {
    return `${this.modalHeader("RANKFORGE 8.8.1", "Neu in dieser Version")}<div class="modal-scroll rf80-centre"><div class="rf80-release-list"><article><span>${icon("palette",18)}</span><div><strong>Workout-Karte in deiner Akzentfarbe</strong><small>Das heutige Training übernimmt wieder die ausgewählte Designfarbe – in Minimal und Detailreich.</small></div></article><article><span>${icon("layout",18)}</span><div><strong>Rank-Listen ein- und ausklappbar</strong><small>Exercise Rankings, Muskel-Ranks, Farb-Legende und Rank Ladder lassen sich kompakt zusammenfassen.</small></div></article><article><span>${icon("user",18)}</span><div><strong>Profilbild sauber rund</strong><small>Die Bildfläche füllt den Avatar jetzt vollständig; dunkle Kanten unter dem Foto sind entfernt.</small></div></article><article><span>${icon("check",18)}</span><div><strong>Funktionalität bleibt erhalten</strong><small>Alle Einträge bleiben anklickbar und der offene Zustand wird pro lokalem Account gespeichert.</small></div></article></div><div class="rf80-centre-actions"><button class="button button--primary button--wide" data-action="rf80-whats-new-done">Verstanden</button></div></div>`;
  };

  proto.init = async function(...args) {
    await previous.init.apply(this, args);
    ensure881(this);
    this.scheduleSave?.();
    this.render();
  };

  window.RANKFORGE881 = Object.freeze({
    version: RF881_VERSION,
    ensure: ensure881,
    isOpen: (app, key) => isOpen881(app, key)
  });
})(LiftoffApp);
/* end-rankforge-v881 */

