    maleBack.lats = "M42,84 C35,86 29,90 27,96 C29,106 34,116 41,123 C47,120 52,113 56,104 L56,98 L48,90 Z M76,84 C83,86 89,90 91,96 C89,106 84,116 77,123 C71,120 66,113 62,104 L62,98 L70,90 Z";
    maleBack.lowerBack = "M55,104 C49,108 44,113 40,121 L41,139 L49,151 L56,138 Z M63,104 C69,108 74,113 78,121 L77,139 L69,151 L62,138 Z";
