/* RANKFORGE 9.1.2 — clean symmetric bodygraphs for both profiles */
(() => {
  "use strict";
  const MALE_ASSETS = Object.freeze({
    front: "./assets/body/male-front-clean-v9.1.2.webp",
    back: "./assets/body/male-back-clean-v9.1.2.webp"
  });
  const FEMALE_LAT_LEFT = "M187 454 C169 456 151 456 139 451 L127 446 C130 472 136 494 143 516 C151 542 162 566 178 589 L207 618 C218 604 225 581 230 555 C234 532 226 507 211 485 Z";
  const FEMALE_LAT_RIGHT = "M325 454 C343 456 361 456 373 451 L385 446 C382 472 376 494 369 516 C361 542 350 566 334 589 L305 618 C294 604 287 581 282 555 C278 532 286 507 301 485 Z";
  const FEMALE_LAT_LINE_LEFT = "M151 473 C166 501 185 538 207 584 M207 584 L219 610";
  const FEMALE_LAT_HIT_LEFT = "M135 420 C165 432 198 470 230 526 L238 575 L216 646 C184 681 149 651 133 607 L118 515 Z";
  const FEMALE_ART = "./assets/female-bodygraph-v9.1.1.png";
  const previousBodyFigure912 = bodyFigure;

  function maleBodyFigure912(view, statuses, selected, options = {}) {
    const assets = window.UPRANK_BODYGRAPH_ASSETS || bodygraphAssets;
    const legacyWidth = Number(assets?.width || 118);
    const legacyHeight = Number(assets?.height || 288);
    const paths = assets?.paths?.[view] || {};
    const order = view === "front" ? FRONT_BODY_MUSCLES : BACK_BODY_MUSCLES;
    const label = options.hideLabel ? "" : `<span>${view === "front" ? "VORNE" : "HINTEN"}</span>`;
    const extraClass = options.className ? ` ${escapeAttr(options.className)}` : "";
    const regions = order
      .map(key => bodyMaskGroup(view, key, statuses, selected, paths[key], options.interactive !== false))
      .join("");
    const scaleX = (1000 / legacyWidth).toFixed(6);
    const scaleY = (2048 / legacyHeight).toFixed(6);
    return `<div class="body-figure body-figure--male-clean-v912${extraClass}">${label}<svg viewBox="0 0 1000 2048" role="img" aria-label="${view === "front" ? "Männliche Vorderseite" : "Männliche Rückseite"} des Muskelstatus"><image class="rf912-male-art" href="${escapeAttr(MALE_ASSETS[view])}" x="0" y="0" width="1000" height="2048" preserveAspectRatio="none" aria-hidden="true"/><g class="rf912-male-regions" transform="scale(${scaleX} ${scaleY})">${regions}</g></svg></div>`;
  }

  function correctedFemaleLat912(markup, interactive) {
    const action = interactive ? ' data-action="select-muscle" data-muscle="lats"' : "";
    const mirror = 'transform="translate(512 0) scale(-1 1)"';
    const region = new RegExp('(<g class="muscle-region muscle-region--lats\\b[^>]*>)[\\s\\S]*?(</g>)');
    markup = markup.replace(region, `$1<path${action} d="${FEMALE_LAT_LEFT}" fill-rule="evenodd" clip-rule="evenodd"/><path${action} d="${FEMALE_LAT_LEFT}" ${mirror} fill-rule="evenodd" clip-rule="evenodd"/><path class="rf911-anatomy-lines" d="${FEMALE_LAT_LINE_LEFT}"/><path class="rf911-anatomy-lines" d="${FEMALE_LAT_LINE_LEFT}" ${mirror}/><path class="rf911-muscle-hit"${action} d="${FEMALE_LAT_HIT_LEFT}"/><path class="rf911-muscle-hit"${action} d="${FEMALE_LAT_HIT_LEFT}" ${mirror}/>$2`);

    const art = /(<image class="rf893-female-art"[^>]*\/>)/;
    const correction = `<defs><clipPath id="rf912-female-right-lat" clipPathUnits="userSpaceOnUse"><path d="${FEMALE_LAT_RIGHT}"/></clipPath></defs><g class="rf912-female-lat-correction" clip-path="url(#rf912-female-right-lat)" aria-hidden="true"><g transform="translate(512 0) scale(-1 1)"><image href="${FEMALE_ART}" x="-512" y="0" width="1024" height="1536" preserveAspectRatio="none"/></g></g>`;
    return markup.replace(art, `$1${correction}`);
  }

  bodyFigure = function(view, statuses, selected, options = {}) {
    const profile = window.RANKFORGE890?.normalizeBodyProfile?.(
      options.bodyProfile || options.sex || window.RANKFORGE_APP?.state?.profile?.bodyProfile || "male",
      "male"
    ) || "male";
    if (profile !== "female") return maleBodyFigure912(view, statuses, selected, options);
    const markup = previousBodyFigure912(view, statuses, selected, options);
    return view === "back" ? correctedFemaleLat912(markup, options.interactive !== false) : markup;
  };

  window.RANKFORGE912_BODYGRAPH = Object.freeze({
    maleAssets: MALE_ASSETS,
    femaleLatLeft: FEMALE_LAT_LEFT,
    femaleLatRight: FEMALE_LAT_RIGHT,
    maleBodyFigure: maleBodyFigure912
  });
})();
